defined('ABSPATH')||exit;get_header();$anon=get_term_by('slug','anonimo','gmr_artist');$artists=get_terms(array('taxonomy'=>'gmr_artist','hide_empty'=>false,'exclude'=>$anon?array($anon->term_id):array()));$artists=is_wp_error($artists)?array():gmr_theme_order_terms($artists,'gmr_artist_order');$visible=array();foreach($artists as$artist){$count=gmr_theme_visible_work_count('gmr_artist',$artist->term_id);if($count||current_user_can('gmr_manage_artworks'))$visible[]=array('term'=>$artist,'count'=>$count,'image'=>gmr_theme_artist_image_id($artist));}$featured_index=0;foreach($visible as$i=>$item)if('elmar-rojas'===$item['term']->slug||get_term_meta($item['term']->term_id,'gmr_artist_featured',true)){$featured_index=$i;break;}if($visible&&$featured_index){$featured=$visible[$featured_index];unset($visible[$featured_index]);array_unshift($visible,$featured);}$total=count($visible);
?>
<header class="gmr-artists-hero"><div class="gmr-wrap"><div class="gmr-artists-hero__meta"><span class="gmr-kicker">Voces y trayectorias</span><span><?php echo esc_html($total);?> artistas</span></div><h1>Artistas</h1><div class="gmr-artists-hero__intro"><p>Una comunidad de creadores modernos y contemporáneos vinculados a la historia de la galería y al desarrollo del arte guatemalteco.</p><span>Archivo de artistas · Galería Mayarí Rojas</span></div></div></header>
<section class="gmr-artists-body"><div class="gmr-wrap"><div class="gmr-artists-bento"><?php foreach($visible as$i=>$item):$artist=$item['term'];$bio=get_term_meta($artist->term_id,'gmr_artist_biography',true);$url=gmr_theme_artist_url($artist);?><article class="gmr-artist-tile <?php echo 0===$i?'gmr-artist-tile--featured':'';?>"><a href="<?php echo esc_url($url);?>"><div class="gmr-artist-tile__image"><?php echo $item['image']?wp_get_attachment_image($item['image'],'large'):wc_placeholder_img('large');?><span></span></div><div class="gmr-artist-tile__body"><div><small><?php echo esc_html($item['count'].' '.(1===$item['count']?'obra':'obras'));?></small><h2><?php echo esc_html($artist->name);?></h2><?php if(0===$i&&$bio):?><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags($bio),26));?></p><?php endif;?></div><i aria-hidden="true">↗</i></div></a></article><?php endforeach;?></div><?php if(!$visible):?><p class="gmr-empty">El archivo de artistas se encuentra en preparación.</p><?php endif;?></div></section>
<section class="gmr-artists-cta"><div class="gmr-wrap"><span class="gmr-kicker">Colección</span><h2>Descubra las obras que forman parte de la galería.</h2><a class="gmr-button" href="<?php echo esc_url(get_post_type_archive_link('product'));?>">Explorar catálogo</a></div></section><?php get_footer();?>
